  if (!want) return;
  if (PREP_ACC_KEYS.indexOf(want) < 0) { want = PREP_ACC_KEYS[0]; try { window.localStorage.setItem(PREP_ACC_KEY, want); } catch (e) {} }   // e.g. a saved 'publish' from before it moved tabs
